export function resolveMapLocale(language) {
  return typeof language === 'string' && language.toLowerCase() === 'pt-br'
    ? 'pt-BR'
    : 'en-US'
}

export function getBrowserMapLocale() {
  return resolveMapLocale(
    typeof window === 'undefined' ? undefined : window.navigator.language,
  )
}

export function getMapI18n(language) {
  const locale = resolveMapLocale(language)
  const messages = mapMessages[locale]
  const formatter = new Intl.NumberFormat(locale)
  return {
    locale,
    format: (value) => formatter.format(value),
    t: (key, values = {}) =>
      (messages[key] ?? mapMessages['en-US'][key] ?? key).replace(
        /\{(\w+)\}/g,
        (match, name) =>
          Object.hasOwn(values, name) ? String(values[name]) : match,
      ),
  }
}
